/**
 * How far back the standing level of a provisioned dimension is hunted for,
 * in days, when nothing new has been read inside the window. Each span is
 * tried in turn so the common case of a recent reading costs one lookup, while
 * a level set long ago is still found.
 */
const STANDING_LEVEL_LOOKBACK_IN_DAYS = [1, 7, 30, 90, 365, 5 * 365];
const ONE_DAY_IN_MS = 864e5;

/**
 * The last reading a series holds before an instant, however long before it
 * was published. A provisioned dimension keeps standing at the level its last
 * reading set, so the level a window opens at can come from well before it.
 */
export const readLatestUsageSampleBefore = async ({
    series,
    before,
}: {
    series: UsageSeries;
    before: Date;
}): Promise<UsageSample | undefined> => {
    for (const days of STANDING_LEVEL_LOOKBACK_IN_DAYS) {
        const samples = await readUsageSamples({
            series,
            startTime: new Date(before.getTime() - days * ONE_DAY_IN_MS),
            endTime: before,
        });
        if (samples.length) {
            return samples.reduce((latest, sample) =>
                new Date(sample.timestamp) > new Date(latest.timestamp) ? sample : latest,
            );
        }
    }
    return undefined;
};
