                        }

                        const usage = steps.map(({ start, end }) => {
                            const readInStep = readings.filter(({ timestamp }) => {
                                const moment = new Date(timestamp);
                                return moment >= start && moment < end;
                            });
                            if (readInStep.length) {
                                standingLevel = readInStep[readInStep.length - 1].value;
                            }
                            const value = readInStep.length
                                ? reduceSamples(
                                      readInStep.map(({ value: reading }) => reading),
                                      argumentAggregationMethod,
                                  )
                                : provisioned && standingLevel !== undefined
                                  ? standingLevel
                                  : 0;
                            return new UsageDocument({
                                value: value.toString(),
                                startTime: start.toISOString(),
                                endTime: end.toISOString(),
                            });
                        }) as UsageResponseDocument[];

                        return { metadataGroup, usage };
                    },
                ),
            );
        },
    };

    static buildAggregationQueries = async ({
        offeringDocument,
        ...rest
    }: UsageAggregationEvent): Promise<
        Array<UnAggregatedUsageResponse | AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse>
    > => {
        const results = await Promise.all(
            offeringDocument.dimensions.map(async ({ dimensionId, ...dimensionRest }) => {
                const curves = await UsageAggregationEvent.dimensionFunctionMap['usageData']({
                    dimension: { ...dimensionRest, dimensionId },
                    ...rest,
                });
                return curves.map(({ metadataGroup, usage }) => ({
                    offeringId: offeringDocument?.offeringId,
                    dimensionId,
                    ...(metadataGroup ? { metadataGroup } : {}),
                    usage,
                }));
            }),
        );
        return results.flat() as Array<
            UnAggregatedUsageResponse | AggregatedUsageResponse | MetadataGroupedAggregatedUsageResponse
        >;
    };

