    } as never)) as never as Array<{ dimensionId: string; metadataGroup?: Record<string, string>; usage: any[] }>;

describe('usage curve', () => {
    test('consumption steps are clock aligned, clamped and zero when unused', async () => {
        const [dimension] = await curve([widgets], '2024-02-14T00:20:00.000Z', '2024-02-14T02:40:00.000Z');
        expect(dimension.usage).toEqual([
            { value: '4', startTime: '2024-02-14T00:20:00.000Z', endTime: '2024-02-14T01:00:00.000Z' },
            { value: '0', startTime: '2024-02-14T01:00:00.000Z', endTime: '2024-02-14T02:00:00.000Z' },
            { value: '18', startTime: '2024-02-14T02:00:00.000Z', endTime: '2024-02-14T02:40:00.000Z' },
        ]);
    });

    test('a provisioned dimension keeps standing at its level', async () => {
        const [dimension] = await curve([licences], '2024-02-14T00:20:00.000Z', '2024-02-14T02:40:00.000Z');
        expect(dimension.usage.map(({ value }) => value)).toEqual(['2', '5', '5']);
    });

    test('a provisioned level set long before the window still opens it', async () => {
        const [dimension] = await curve([licences], '2024-02-13T00:00:00.000Z', '2024-02-14T00:00:00.000Z');
        expect(dimension.usage).toHaveLength(24);
        expect(dimension.usage.every(({ value }) => value === '2')).toBe(true);
    });

    test('each published group of a metadata priced dimension is reported on its own', async () => {
        const groups = await curve([egress], '2024-02-14T00:00:00.000Z', '2024-02-14T03:00:00.000Z');
        expect(groups).toHaveLength(2);
        expect(groups[0].metadataGroup).toEqual({ environment: 'production' });
        expect(groups[0].usage.map(({ value }) => value)).toEqual(['3', '0', '1']);
        expect(groups[1].metadataGroup).toEqual({ environment: 'staging' });
        expect(groups[1].usage.map(({ value }) => value)).toEqual(['0', '9', '0']);
    });

    test('every step comes back even for a customer with no readings', async () => {
        const [dimension] = await curve(
            [widgets],
            '2024-02-14T00:00:00.000Z',
            '2024-02-14T03:00:00.000Z',
            'cus_nobody',
        );
        expect(dimension.usage).toEqual([
            { value: '0', startTime: '2024-02-14T00:00:00.000Z', endTime: '2024-02-14T01:00:00.000Z' },
            { value: '0', startTime: '2024-02-14T01:00:00.000Z', endTime: '2024-02-14T02:00:00.000Z' },
            { value: '0', startTime: '2024-02-14T02:00:00.000Z', endTime: '2024-02-14T03:00:00.000Z' },
        ]);
    });

    test('daily steps hold a whole day and clamp to the window', async () => {
        const [dimension] = await curve(
            [{ ...widgets, aggregationInterval: aggregationInterval.day }],
            '2024-02-13T12:00:00.000Z',
            '2024-02-14T06:00:00.000Z',
        );
        expect(dimension.usage).toEqual([
            { value: '0', startTime: '2024-02-13T12:00:00.000Z', endTime: '2024-02-14T00:00:00.000Z' },
            { value: '26', startTime: '2024-02-14T00:00:00.000Z', endTime: '2024-02-14T06:00:00.000Z' },
        ]);
    });

    test('monthly steps open on the first of the month', async () => {
        const [dimension] = await curve(
            [{ ...widgets, aggregationInterval: aggregationInterval.month }],
            '2024-01-15T00:00:00.000Z',
            '2024-03-01T00:00:00.000Z',
        );
        expect(dimension.usage).toEqual([
            { value: '0', startTime: '2024-01-15T00:00:00.000Z', endTime: '2024-02-01T00:00:00.000Z' },
            { value: '26', startTime: '2024-02-01T00:00:00.000Z', endTime: '2024-03-01T00:00:00.000Z' },
        ]);
    });

    test('raw readings still come back when no interval is asked for', async () => {
        const [dimension] = await curve(
            [{ ...widgets, aggregationInterval: aggregationInterval.none }],
            '2024-02-14T00:00:00.000Z',
            '2024-02-14T03:00:00.000Z',
        );
        expect(dimension.usage).toHaveLength(8);
        expect(dimension.usage[0]).toEqual({
            timestamp: '2024-02-14T00:15:00.000Z',
            recordValue: '4',
            metadata: {},
        });
    });
});
