import { stepsOfWindow } from './usageAggregation.event.js';
import { aggregationInterval } from '../dimensions/dto/create-dimension.dto.js';

const edges = (steps: Array<{ start: Date; end: Date }>) =>
    steps.map(({ start, end }) => [start.toISOString(), end.toISOString()]);

describe('stepsOfWindow', () => {
    it('should sit the step edges on the clock and clamp the first and last one to the window', () => {
        expect(
            edges(
                stepsOfWindow({
                    startTime: '2024-02-14T00:20:00.000Z',
                    endTime: '2024-02-14T02:40:00.000Z',
                    interval: aggregationInterval.hour,
                }),
            ),
        ).toEqual([
            ['2024-02-14T00:20:00.000Z', '2024-02-14T01:00:00.000Z'],
            ['2024-02-14T01:00:00.000Z', '2024-02-14T02:00:00.000Z'],
            ['2024-02-14T02:00:00.000Z', '2024-02-14T02:40:00.000Z'],
        ]);
    });

    it('should hand back the one step a window inside a single step covers', () => {
        expect(
            edges(
                stepsOfWindow({
                    startTime: '2024-02-14T00:20:00.000Z',
                    endTime: '2024-02-14T00:35:00.000Z',
                    interval: aggregationInterval.hour,
                }),
            ),
        ).toEqual([['2024-02-14T00:20:00.000Z', '2024-02-14T00:35:00.000Z']]);
    });

    it('should open daily steps at midnight', () => {
        expect(
            edges(
                stepsOfWindow({
                    startTime: '2024-02-13T12:00:00.000Z',
                    endTime: '2024-02-15T06:00:00.000Z',
