const ONE_HOUR_IN_MS = 36e5;

/** One step of a window, already clamped to it. */
export type UsageStep = { start: Date; end: Date };

/**
 * The curve one published group of a dimension holds: a value for every step of
 * the window, and the metadata group the readings behind it carry, if any.
 */
export type DimensionUsageCurve = {
    metadataGroup?: Record<string, string>;
    usage: UsageResponseDocument[] | BasicUsageDocument[];
};

/** A set of readings published together, and the metadata group they carry. */
type PublishedGroup = { metadataGroup?: Record<string, string>; series: UsageSeries[] };

/** The clock edge the step holding an instant opens on. */
const alignToStep = (moment: Date, interval: aggregationInterval): Date => {
    const aligned = new Date(moment.getTime());
    switch (interval) {
        case aggregationInterval.month:
            aligned.setUTCDate(1);
            aligned.setUTCHours(0, 0, 0, 0);
            break;
        case aggregationInterval.day:
            aligned.setUTCHours(0, 0, 0, 0);
            break;
        default:
            aligned.setUTCMinutes(0, 0, 0);
    }
    return aligned;
};

/** The clock edge the step after the one opening on an edge opens on. */
const nextStepEdge = (edge: Date, interval: aggregationInterval): Date => {
    const next = new Date(edge.getTime());
    switch (interval) {
        case aggregationInterval.month:
            next.setUTCMonth(next.getUTCMonth() + 1, 1);
            next.setUTCHours(0, 0, 0, 0);
            break;
        case aggregationInterval.day:
            next.setUTCDate(next.getUTCDate() + 1);
            next.setUTCHours(0, 0, 0, 0);
            break;
        default:
            next.setTime(next.getTime() + ONE_HOUR_IN_MS);
    }
    return next;
};

/**
 * Every step a window is asked for, one per interval it covers. The edges sit
 * on the clock, so a window opening mid step still hands back that step, with
 * the first and the last one clamped to the window itself.
 */
export const stepsOfWindow = ({
    startTime,
    endTime,
    interval,
}: {
    startTime: string;
    endTime: string;
    interval: aggregationInterval;
}): UsageStep[] => {
    const windowStart = new Date(startTime);
    const windowEnd = new Date(endTime);
    const steps: UsageStep[] = [];
    if (!(windowEnd > windowStart)) {
        return steps;
    }
    let edge = alignToStep(windowStart, interval);
    while (edge < windowEnd) {
        const next = nextStepEdge(edge, interval);
        steps.push({
            start: edge < windowStart ? windowStart : edge,
            end: next > windowEnd ? windowEnd : next,
        });
        edge = next;
    }
    return steps;
};

/** Readings ordered oldest first, the way a level is built up over time. */
const oldestFirst = (samples: UsageSample[]): UsageSample[] =>
    [...samples].sort((left, right) => new Date(left.timestamp).getTime() - new Date(right.timestamp).getTime());

/**
 * A provisioned dimension stands at a level until a new reading moves it, so
 * the level carries through steps nothing new was read in. Anything else is
 * consumed inside a step and is simply not there when nothing was read.
 */
const isProvisioned = (dimension: ReadDimensionResponseData): boolean => {
    const { sampleType, paymentSchedule } = dimension ?? ({} as ReadDimensionResponseData);
    if (sampleType) {
        return sampleType === SampleType.continious;
    }
    return paymentSchedule === PaymentSchedule.upfront;
};

/** A dimension priced off the metadata its readings carry. */
const isPricedByMetadata = (dimension: ReadDimensionResponseData): boolean =>
    Boolean(dimension?.tiersGroupByMetadata && dimension.tiersGroupByMetadata.length > 0);

/**
 * How the series published for a dimension are reported. A dimension priced by
 * metadata is reported a group at a time, so each published group keeps its own
 * curve, while any other dimension pools every series it has into one.
 */
const publishedGroupsOf = (dimension: ReadDimensionResponseData, published: UsageSeries[]): PublishedGroup[] => {
    if (!isPricedByMetadata(dimension)) {
        return [{ series: published }];
    }
    const groups = published.map((series) => {
        const metadata = metadataOf(series);
        return { metadataGroup: Object.keys(metadata).length ? metadata : undefined, series: [series] };
    });
    // Even a dimension nothing has been published for still owes the caller its steps.
    return groups.length ? groups : [{ series: published }];
"
}

